// devices whose Model matches any of the
// provided values.
func MatchModels(vals ...string) Filter {
	return func(Retrieve) gorp.Filter[Key, Device] {
		want := set.New(vals...)
		return gorp.Match(func(_ gorp.Context, e *Device) (bool, error) {
			return want.Contains(e.Model), nil
		})
	}
}

// MatchChassisList returns a filter for devices
// whose Chassis matches any of the provided
// values.
func MatchChassisList(vals ...chassis.Key) Filter {
	return func(r Retrieve) gorp.Filter[Key, Device] {
		return r.indexes.chassis.Filter(vals...)
	}
}

// MatchHasChassis returns a filter for devices whose
// Chassis holds a target when has is true, and holds none when has is false.
func MatchHasChassis(has bool) Filter {
	return func(r Retrieve) gorp.Filter[Key, Device] {
		return r.indexes.chassis.FilterHolding(has)
	}
}

// Where applies the provided filter to the query, binding it to the Retrieve
// so service-bound filters can read from r.indexes, r.label, r.hostProvider,
// etc. To compose multiple filters, chain Where calls or pass a combined
// filter via And / Or.
func (r Retrieve) Where(filter Filter) Retrieve {
	r.gorp = r.gorp.Where(filter(r))
	return r
}

// Entry binds the provided device as the result container for the
// query. If multiple devices match, the first one is
// used.
func (r Retrieve) Entry(e *Device) Retrieve {
	r.gorp = r.gorp.Entry(e)
	return r
}

// Entries binds the provided slice of devices as the
// result container for the query.
func (r Retrieve) Entries(es *[]Device) Retrieve {
	r.gorp = r.gorp.Entries(es)
	return r
}

// Limit sets the maximum number of devices to return.
func (r Retrieve) Limit(limit int) Retrieve { r.gorp = r.gorp.Limit(limit); return r }

// After starts the query strictly past key in key order. It panics on a query with an
// OrderBy, since an Order carries its own cursor.
func (r Retrieve) After(key Key) Retrieve {
	r.gorp = r.gorp.After(key)
	return r
}

// SkipMissingKeys makes Exec treat a key with no device as a
// non-match instead of returning query.ErrNotFound.
func (r Retrieve) SkipMissingKeys() Retrieve {
	r.gorp = r.gorp.SkipMissingKeys()
	return r
}

// Exec executes the query against snap. It panics when snap is nil.
func (r Retrieve) Exec(ctx context.Context, snap gorp.Snapshot) error {
	return r.gorp.Exec(ctx, snap)
}

// Count returns the number of devices in snap that match
// the query. It panics when snap is nil.
func (r Retrieve) Count(ctx context.Context, snap gorp.Snapshot) (int, error) {
	return r.gorp.Count(ctx, snap)
}

// Exists checks whether any devices in snap match the
// query. It panics when snap is nil.
func (r Retrieve) Exists(ctx context.Context, snap gorp.Snapshot) (bool, error) {
	return r.gorp.Exists(ctx, snap)
}
